          kind: "image",
          name: "diagram.png",
          mimeType: "image/png",
          size: 512,
          uri: "file:///documents/composer-attachments/diagram.png",
        }],
      }, {
        id: "message-branch-assistant",
        role: "assistant",
        content: "What changes when the prior changes?",
        createdAt: 1_786_310_030_000,
        provider: "openai",
