void SplashScreen.preventAutoHideAsync();

function AppNavigator() {
  const { hydrated } = useKeating();
  const theme = useKeatingTheme();
  const { loaded: settingsLoaded } = useUiSettings();
  const [fontsLoaded] = useFonts({
