      id: `goal:${goal.id}`,
      targetId: goal.id,
      targetType: "goal",
      ...laneFor(priorities, "goal", goal.id, topic, completed > 0 ? "focus" : "maintain"),
      title: goal.title,
      topic,
      description: goal.steps.find((step) => step.status !== "done")?.title ?? goal.description,
      dueCount: 0,
      overdueCount: 0,
      nextDueAt: null,
      estimatedMinutes: 5,
      cardCount: 0,
      createdAt: goal.updatedAt,
